def migrate_legacy_invoice_payments(apps, schema_editor):
    Invoice = apps.get_model('payment', 'Invoice')
    Payment = apps.get_model('payment', 'Payment')
    PaymentReceipt = apps.get_model('payment', 'PaymentReceipt')
    db_alias = schema_editor.connection.alias

    for invoice in Invoice.objects.using(db_alias).select_related('service_request').iterator():
        receipt_name = invoice.payment_receipt.name if invoice.payment_receipt else ''
        is_verified = invoice.payment_verified
        if not receipt_name and not is_verified:
            continue

        is_advance = bool(
            invoice.service_request_id
            and invoice.service_request
            and invoice.service_request.advance_payment_paid
        )
        amount = invoice.advance_payment if is_advance else invoice.remaining_amount
        payment = Payment.objects.using(db_alias).create(
            invoice_id=invoice.pk,
            payment_type='advance' if is_advance else 'final',
            amount=amount or invoice.total,
            status='verified' if is_verified else 'submitted',
            paid_at=invoice.paid_at,
            verified_at=invoice.paid_at if is_verified else None,
        )
        if receipt_name:
            PaymentReceipt.objects.using(db_alias).create(
                payment_id=payment.pk,
                image=receipt_name,
            )


def restore_legacy_invoice_payments(apps, schema_editor):
    Invoice = apps.get_model('payment', 'Invoice')
    Payment = apps.get_model('payment', 'Payment')
    PaymentReceipt = apps.get_model('payment', 'PaymentReceipt')
    db_alias = schema_editor.connection.alias

    for invoice in Invoice.objects.using(db_alias).iterator():
        payment = Payment.objects.using(db_alias).filter(invoice_id=invoice.pk).order_by('-created_at').first()
        if not payment:
            continue
        receipt = PaymentReceipt.objects.using(db_alias).filter(payment_id=payment.pk).first()
        invoice.payment_verified = payment.status == 'verified'
        if receipt:
            invoice.payment_receipt = receipt.image.name
        invoice.save(using=db_alias, update_fields=['payment_verified', 'payment_receipt'])


